6	struct ControllerScreen: View {
7	    let address: RobotAddress
8	
9	    @State private var client: SetTargetClient?
10	    @State private var target = SetTargetClient.Target()
11	    @State private var setupError: String?
12	
13	    // Comfortable UI ranges; hardware limits (clamped by the daemon anyway):
14	    // head pitch/roll ±40°, yaw ±180°, body yaw ±180°
15	    private let headAngle = 40.0 * .pi / 180
16	    private let fullTurn = 180.0 * .pi / 180
17	    private let antennaRange = 150.0 * .pi / 180
18	
19	    var body: some View {
20	        Form {
21	            Section("Head — drag: yaw / pitch") {
22	                JoystickPad { x, y in
23	                    target.yaw = -x * headAngle
24	                    target.pitch = y * headAngle
