65	    private enum SliderFormat { case degrees, millimeters }
66	
67	    private func slider(
68	        _ title: String,
69	        value: Binding<Double>,
70	        range: ClosedRange<Double>,
71	        format: SliderFormat
72	    ) -> some View {
73	        VStack(alignment: .leading, spacing: 2) {
74	            HStack {
75	                Text(title)
