3	/// Cumulative, privacy-safe health information for one state-stream subscription.
4	public struct StateStreamDiagnostics: Equatable, Sendable {
5	    public var receivedFrames = 0
6	    public var decodedFrames = 0
7	    public var decodeFailures = 0
8	    public var unsupportedFrames = 0
9	    public var lastFailureDescription: String?
10	    public var lastFailureAt: Date?
11	
12	    public init() {}
13	}
14	
15	/// One WebSocket frame and the diagnostics accumulated through that frame.
16	public struct StateStreamUpdate: Sendable {
17	    public let state: Components.Schemas.FullState?
18	    public let diagnostics: StateStreamDiagnostics
19	}
20	
21	/// Streams the robot's full state from `ws://<host>:<port>/api/state/ws/full` (20 Hz).
22	///
23	/// Reconnects forever with exponential backoff until the stream's consumer cancels.
24	/// Streams use `.bufferingNewest(1)`, so slow consumers always observe the newest update.
25	public struct StateStreamClient: Sendable {
26	    public struct Configuration: Sendable {
27	        public var initialBackoff: Duration = .milliseconds(500)
28	        public var maxBackoff: Duration = .seconds(15)
29	        public init() {}
30	    }
31	
32	    public static let statePath = "/api/state/ws/full"
33	
34	    private let url: URL
35	    private let configuration: Configuration
36	    private let session: URLSession
37	
38	    public init(
39	        address: RobotAddress,
40	        configuration: Configuration = .init(),
41	        session: URLSession = .shared
42	    ) throws {
43	        guard let url = address.webSocketURL(path: Self.statePath) else {
44	            throw ReachyKitError.invalidAddress(address)
45	        }
46	        self.url = url
47	        self.configuration = configuration
48	        self.session = session
49	    }
50	
51	    /// Latest-wins state plus cumulative frame diagnostics. A malformed frame is
52	    /// reported and skipped without reconnecting or terminating the stream.
53	    public func updates() -> AsyncStream<StateStreamUpdate> {
54	        let (stream, continuation) = AsyncStream.makeStream(
55	            of: StateStreamUpdate.self,
56	            bufferingPolicy: .bufferingNewest(1)
57	        )
58	        let task = Task { [url, configuration, session] in
59	            let decoder = JSONDecoder.reachyDaemon
60	            var backoff = configuration.initialBackoff
61	            var diagnostics = StateStreamDiagnostics()
62	            while !Task.isCancelled {
63	                let socket = session.webSocketTask(with: url)
64	                socket.resume()
65	                do {
66	                    while !Task.isCancelled {
67	                        let message = try await socket.receive()
68	                        diagnostics.receivedFrames += 1
69	                        let data: Data?
70	                        switch message {
71	                        case let .data(payload):
72	                            data = payload
73	                        case let .string(text):
74	                            data = Data(text.utf8)
75	                        @unknown default:
76	                            data = nil
77	                            diagnostics.unsupportedFrames += 1
78	                            diagnostics.lastFailureDescription = "Unsupported WebSocket frame type"
79	                            diagnostics.lastFailureAt = Date()
80	                        }
81	
82	                        guard let data else {
83	                            continuation.yield(.init(state: nil, diagnostics: diagnostics))
84	                            continue
85	                        }
86	                        do {
87	                            let state = try decoder.decode(Components.Schemas.FullState.self, from: data)
88	                            diagnostics.decodedFrames += 1
89	                            continuation.yield(.init(state: state, diagnostics: diagnostics))
90	                            backoff = configuration.initialBackoff
91	                        } catch {
92	                            diagnostics.decodeFailures += 1
93	                            diagnostics.lastFailureDescription = Self.failureDescription(error)
94	                            diagnostics.lastFailureAt = Date()
95	                            continuation.yield(.init(state: nil, diagnostics: diagnostics))
96	                        }
97	                    }
98	                } catch {
99	                    socket.cancel(with: .goingAway, reason: nil)
100	                }
101	                guard !Task.isCancelled else { break }
102	                try? await Task.sleep(for: backoff)
103	                backoff = min(backoff * 2, configuration.maxBackoff)
104	            }
105	            continuation.finish()
106	        }
107	        continuation.onTermination = { _ in task.cancel() }
108	        return stream
109	    }
110	
111	    /// Compatibility wrapper for consumers interested only in valid states.
112	    public func states() -> AsyncStream<Components.Schemas.FullState> {
113	        let (stream, continuation) = AsyncStream.makeStream(
114	            of: Components.Schemas.FullState.self,
115	            bufferingPolicy: .bufferingNewest(1)
116	        )
117	        let task = Task {
118	            for await update in updates() {
119	                if let state = update.state {
120	                    continuation.yield(state)
121	                }
122	            }
123	            continuation.finish()
124	        }
125	        continuation.onTermination = { _ in task.cancel() }
126	        return stream
127	    }
128	
129	    private static func failureDescription(_ error: any Error) -> String {
130	        String(describing: error).prefix(240).description
131	    }
132	}
