3	/// Network address of a robot daemon. Port is configurable (upstream hardcodes 8000).
4	public struct RobotAddress: Hashable, Sendable, Codable {
5	    public var host: String
6	    public var port: Int
7	
8	    public static let defaultPort = 8000
9	
10	    public init(host: String, port: Int = RobotAddress.defaultPort) {
11	        self.host = host
12	        self.port = port
13	    }
14	
15	    /// Parses user input: `host`, `host:port`, `[v6]`, `[v6]:port`, or bare IPv6.
16	    /// Users paste addresses with ports (phase-0 device testing proved it) — a bare
17	    /// `host` field that treats ":" as IPv6 produces garbage URLs.
18	    public init?(parsing input: String) {
19	        let s = input.trimmingCharacters(in: .whitespaces)
20	        guard !s.isEmpty else { return nil }
21	
22	        if s.hasPrefix("[") {
23	            guard let end = s.firstIndex(of: "]") else { return nil }
24	            let host = String(s[s.index(after: s.startIndex) ..< end])
25	            let rest = s[s.index(after: end)...]
26	            if rest.isEmpty {
27	                self.init(host: host)
28	            } else if rest.hasPrefix(":"), let port = Int(rest.dropFirst()) {
29	                self.init(host: host, port: port)
30	            } else {
31	                return nil
32	            }
33	            return
34	        }
35	
36	        switch s.count(where: { $0 == ":" }) {
37	        case 0:
38	            self.init(host: s)
39	        case 1:
40	            guard let i = s.firstIndex(of: ":"), let port = Int(s[s.index(after: i)...]) else { return nil }
41	            self.init(host: String(s[..<i]), port: port)
42	        default:
43	            // Multiple colons: bare IPv6 literal
44	            self.init(host: s)
45	        }
46	    }
47	
48	    /// Root URL of the daemon, e.g. `http://reachy-mini.local:8000`.
49	    /// Generated OpenAPI operation paths already include the `/api` prefix.
50	    public var rootURL: URL? {
51	        url(scheme: "http", path: "")
52	    }
53	
54	    /// URL for a WebSocket endpoint, e.g. `ws://host:8000/api/state/ws/full`.
55	    public func webSocketURL(path: String) -> URL? {
56	        url(scheme: "ws", path: path)
57	    }
58	
59	    /// Foundation's `URLComponents` rejects bare IPv6 literals in `host` — they must be
60	    /// pre-bracketed by the caller (upstream issue #269 was exactly this class of bug).
61	    private func url(scheme: String, path: String) -> URL? {
62	        guard !host.isEmpty else { return nil }
63	        var components = URLComponents()
64	        components.scheme = scheme
65	        components.host = host.contains(":") && !host.hasPrefix("[") ? "[\(host)]" : host
66	        components.port = port
67	        components.path = path
68	        return components.url
69	    }
70	}
