import simd

/// Rigid-body maths shared by the URDF model, the state stream and the Stewart
/// solver.
///
/// Euler conventions are the single largest source of silent errors here, so
/// there is exactly one implementation of each direction and everything routes
/// through it.
public enum RigidTransform {
    /// URDF `rpy`: intrinsic x-y-z, which composes as `Rz(yaw) * Ry(pitch) * Rx(roll)`.
    public static func rotation(rpy: SIMD3<Double>) -> simd_double3x3 {
        let (sr, cr) = (sin(rpy.x), cos(rpy.x))
        let (sp, cp) = (sin(rpy.y), cos(rpy.y))
        let (sy, cy) = (sin(rpy.z), cos(rpy.z))
        return simd_double3x3(rows: [
            SIMD3(cy * cp, cy * sp * sr - sy * cr, cy * sp * cr + sy * sr),
            SIMD3(sy * cp, sy * sp * sr + cy * cr, sy * sp * cr - cy * sr),
            SIMD3(-sp, cp * sr, cp * cr),
        ])
    }

    /// Inverse of ``rotation(rpy:)``. Extrinsic X-Y-Z extraction, matching
    /// `scipy`'s `as_euler("XYZ")`.
    public static func euler(from rotation: simd_double3x3) -> SIMD3<Double> {
        // Column-major storage: `rotation[column][row]`.
        let sy = -rotation[0][2]
        guard abs(sy) < Self.gimbalLockThreshold else {
            // Pitch at ±90°: roll and yaw fold into one axis, so pin roll to 0.
            return SIMD3(0, sy > 0 ? .pi / 2 : -.pi / 2, atan2(-rotation[1][0], rotation[1][1]))
        }
        return SIMD3(
            atan2(rotation[1][2], rotation[2][2]),
            asin(sy),
            atan2(rotation[0][1], rotation[0][0])
        )
    }

    public static func transform(translation: SIMD3<Double>, rpy: SIMD3<Double>) -> simd_double4x4 {
        var matrix = simd_double4x4(rotation(rpy: rpy))
        matrix.columns.3 = SIMD4(translation, 1)
        return matrix
    }

    /// The daemon sends 4x4 poses flattened row by row; simd stores columns.
    public static func matrix(rowMajor values: [Double]) -> simd_double4x4? {
        guard values.count == 16 else { return nil }
        return simd_double4x4(rows: [
            SIMD4(values[0], values[1], values[2], values[3]),
            SIMD4(values[4], values[5], values[6], values[7]),
            SIMD4(values[8], values[9], values[10], values[11]),
            SIMD4(values[12], values[13], values[14], values[15]),
        ])
    }

    /// Rotation about `axis` by `angle`, for URDF revolute joints.
    public static func rotation(axis: SIMD3<Double>, angle: Double) -> simd_double3x3 {
        simd_double3x3(simd_quatd(angle: angle, axis: simd_normalize(axis)))
    }

    private static let gimbalLockThreshold = 0.99999
}

public extension simd_double4x4 {
    var rotation: simd_double3x3 {
        simd_double3x3(columns.0.xyz, columns.1.xyz, columns.2.xyz)
    }

    var translation: SIMD3<Double> {
        columns.3.xyz
    }
}

extension SIMD4<Double> {
    var xyz: SIMD3<Double> { SIMD3(x, y, z) }
}

import Foundation
import simd

/// A state-stream frame decoded by hand, for consumers that need the geometry.
///
/// The generated `FullState` cannot carry a matrix head pose usefully: the
/// generator does not understand `prefixItems` without `items`, so
/// `Matrix4x4Pose.m` arrives as an untyped `OpenAPIArrayContainer` whose elements
/// have to be cast back from `Any` one by one. Decoding the frame a second time
/// keeps the 3D viewer independent of that quirk, and costs a few microseconds
/// on a ~600-byte payload.
public struct RobotStateFrame: Sendable, Equatable, Decodable {
    public enum HeadPose: Sendable, Equatable {
        /// Sixteen values, row-major, translation in metres.
        case matrix([Double])
        /// Metres and radians.
        case euler(x: Double, y: Double, z: Double, roll: Double, pitch: Double, yaw: Double)

        /// Both forms collapse to the same transform, so callers never branch.
        public var transform: simd_double4x4? {
            switch self {
            case let .matrix(values):
                RigidTransform.matrix(rowMajor: values)
            case let .euler(x, y, z, roll, pitch, yaw):
                RigidTransform.transform(translation: SIMD3(x, y, z), rpy: SIMD3(roll, pitch, yaw))
            }
        }
    }

    public var timestamp: Date?
    public var bodyYaw: Double?
    /// Seven values: `[body_yaw, stewart_1 ... stewart_6]`. Absent unless the
    /// stream was opened with `StateStreamOptions.headJoints`.
    public var headJoints: [Double]?
    /// Two values, `(left, right)`, radians.
    public var antennas: [Double]?
    public var headPose: HeadPose?
    /// Twenty-one values, and only from a Placo-backed daemon.
    public var passiveJoints: [Double]?

    private enum CodingKeys: String, CodingKey {
        case timestamp
        case bodyYaw = "body_yaw"
        case headJoints = "head_joints"
        case antennas = "antennas_position"
        case headPose = "head_pose"
        case passiveJoints = "passive_joints"
    }

    private enum PoseKeys: String, CodingKey {
        case m, x, y, z, roll, pitch, yaw
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        timestamp = try container.decodeIfPresent(Date.self, forKey: .timestamp)
        bodyYaw = try container.decodeIfPresent(Double.self, forKey: .bodyYaw)
        headJoints = try container.decodeIfPresent([Double].self, forKey: .headJoints)
        antennas = try container.decodeIfPresent([Double].self, forKey: .antennas)
        passiveJoints = try container.decodeIfPresent([Double].self, forKey: .passiveJoints)
        headPose = try Self.decodeHeadPose(from: container)
    }

    /// `head_pose` is an `anyOf` whose shape follows the stream's `use_pose_matrix`
    /// flag, so the branch is chosen by looking for `m` rather than by trying both.
    private static func decodeHeadPose(
        from container: KeyedDecodingContainer<CodingKeys>
    ) throws -> HeadPose? {
        guard container.contains(.headPose), try !container.decodeNil(forKey: .headPose) else {
            return nil
        }
        let pose = try container.nestedContainer(keyedBy: PoseKeys.self, forKey: .headPose)
        if let values = try pose.decodeIfPresent([Double].self, forKey: .m) {
            return .matrix(values)
        }
        // Every component defaults to 0 in the daemon's schema.
        return .euler(
            x: try pose.decodeIfPresent(Double.self, forKey: .x) ?? 0,
            y: try pose.decodeIfPresent(Double.self, forKey: .y) ?? 0,
            z: try pose.decodeIfPresent(Double.self, forKey: .z) ?? 0,
            roll: try pose.decodeIfPresent(Double.self, forKey: .roll) ?? 0,
            pitch: try pose.decodeIfPresent(Double.self, forKey: .pitch) ?? 0,
            yaw: try pose.decodeIfPresent(Double.self, forKey: .yaw) ?? 0
        )
    }
}

