@testable import ReachyKit
import simd
import Testing

@Suite("Rigid transform maths")
struct RigidTransformTests {
    /// The daemon flattens poses row by row while simd stores columns. Sixteen
    /// distinct values are the only way to catch a transposition — a symmetric
    /// fixture would pass either way.
    @Test("row-major values land in the right cells")
    func rowMajorUnpacking() throws {
        let values = (1 ... 16).map(Double.init)
        let matrix = try #require(RigidTransform.matrix(rowMajor: values))
        for row in 0 ..< 4 {
            for column in 0 ..< 4 {
                #expect(matrix[column][row] == values[row * 4 + column])
            }
        }
    }

    @Test("rejects a wrong-sized pose")
    func rowMajorRejectsShortInput() {
        #expect(RigidTransform.matrix(rowMajor: Array(repeating: 0, count: 15)) == nil)
    }

    @Test(
        "euler extraction inverts euler construction",
        arguments: [
            SIMD3(0.0, 0.0, 0.0),
            SIMD3(0.3, -0.2, 1.1),
            SIMD3(-1.2, 0.7, -2.5),
            SIMD3(3.0, -1.4, 0.1),
            SIMD3(-0.13754, -0.0882156, 2.10349), // passive_1_x in the robot's URDF
        ]
    )
    func eulerRoundTrip(rpy: SIMD3<Double>) {
        let recovered = RigidTransform.euler(from: RigidTransform.rotation(rpy: rpy))
        // Compare rotations, not angles: different triplets can name one rotation.
        let original = RigidTransform.rotation(rpy: rpy)
        let rebuilt = RigidTransform.rotation(rpy: recovered)
        for column in 0 ..< 3 {
            for row in 0 ..< 3 {
                #expect(abs(original[column][row] - rebuilt[column][row]) < 1e-9)
            }
        }
    }

    @Test("gimbal lock still reproduces the rotation", arguments: [1.0, -1.0])
    func gimbalLock(sign: Double) {
        let rpy = SIMD3(0.4, sign * .pi / 2, 1.3)
        let original = RigidTransform.rotation(rpy: rpy)
        let rebuilt = RigidTransform.rotation(rpy: RigidTransform.euler(from: original))
        for column in 0 ..< 3 {
            for row in 0 ..< 3 {
                #expect(abs(original[column][row] - rebuilt[column][row]) < 1e-9)
            }
        }
    }

    @Test("transform keeps translation in the last column")
    func transformTranslation() {
        let matrix = RigidTransform.transform(
            translation: SIMD3(0.04, -0.5, 0.177),
            rpy: SIMD3(0.1, 0.2, 0.3)
        )
        #expect(abs(matrix.translation.x - 0.04) < 1e-12)
        #expect(abs(matrix.translation.y + 0.5) < 1e-12)
        #expect(abs(matrix.translation.z - 0.177) < 1e-12)
        #expect(matrix[3][3] == 1)
    }

    @Test("axis rotation matches the equivalent rpy")
    func axisRotation() {
        let byAxis = RigidTransform.rotation(axis: SIMD3(0, 0, 1), angle: 0.7)
        let byEuler = RigidTransform.rotation(rpy: SIMD3(0, 0, 0.7))
        for column in 0 ..< 3 {
            for row in 0 ..< 3 {
                #expect(abs(byAxis[column][row] - byEuler[column][row]) < 1e-12)
            }
        }
    }
}

import Foundation
@testable import ReachyKit
import Testing

@Suite("State stream options")
struct StateStreamOptionsTests {
    /// Existing screens and the daemon-compatibility tests rely on the stream URL
    /// staying exactly as it was before options existed.
    @Test("default options add no query at all")
    func defaultsProduceNoQuery() throws {
        let client = try StateStreamClient(address: RobotAddress(host: "robot.local"))
        #expect(client.url.absoluteString == "ws://robot.local:8000/api/state/ws/full")
        #expect(URLComponents(url: client.url, resolvingAgainstBaseURL: false)?.query == nil)
    }

    @Test("visualization asks for motor angles and a matrix pose")
    func visualizationQuery() throws {
        var configuration = StateStreamClient.Configuration()
        configuration.options = .visualization
        let client = try StateStreamClient(
            address: RobotAddress(host: "robot.local"),
            configuration: configuration
        )
        let query = try #require(URLComponents(url: client.url, resolvingAgainstBaseURL: false)?.query)
        #expect(query == [
            "frequency=20",
            "with_head_pose=true",
            "with_head_joints=true",
            "with_body_yaw=true",
            "with_antenna_positions=true",
            "use_pose_matrix=true",
        ].joined(separator: "&"))
    }

    /// The daemon's `with_target_*` flags trip an assertion that a blanket `except`
    /// swallows, leaving a stream that is open but permanently silent. Keeping them
    /// unrepresentable is the fix; this test states the intent so a future author
    /// does not "complete" the option set.
    @Test("no option maps to a with_target_* parameter")
    func targetParametersAreUnreachable() {
        var options = StateStreamOptions()
        options.frequency = 20
        options.headPose = true
        options.headJoints = true
        options.bodyYaw = true
        options.antennaPositions = true
        options.passiveJoints = true
        options.directionOfArrival = true
        options.poseAsMatrix = true
        let names = options.queryItems.map(\.name)
        #expect(names.allSatisfy { !$0.hasPrefix("with_target") })
    }

    @Test("booleans set to false are sent explicitly")
    func explicitFalse() {
        var options = StateStreamOptions()
        options.directionOfArrival = false
        #expect(options.queryItems == [URLQueryItem(name: "with_doa", value: "false")])
    }

    @Test("a whole frequency is not spelled with a decimal point")
    func frequencyFormatting() {
        var options = StateStreamOptions()
        options.frequency = 20
        #expect(options.queryItems.first?.value == "20")
        options.frequency = 12.5
        #expect(options.queryItems.first?.value == "12.5")
    }
}

