}

import Foundation
import simd

/// The subset of URDF this client needs to draw a robot: a link tree, joint
/// frames, and which mesh belongs where.
///
/// Inertia, collision geometry, transmissions and Gazebo extensions are dropped
/// while parsing — nothing here simulates physics.
public struct URDFDocument: Sendable, Equatable {
    public let name: String
    public let links: [URDFLink]
    public let joints: [URDFJoint]

    private let linksByName: [String: URDFLink]
    private let jointsByName: [String: URDFJoint]
    private let jointsByParent: [String: [URDFJoint]]
    private let parentJoint: [String: URDFJoint]

    /// The one link no joint lists as a child.
    public let rootLinkName: String

    public init(name: String, links: [URDFLink], joints: [URDFJoint]) throws {
        self.name = name
        self.links = links
        self.joints = joints
        linksByName = Dictionary(links.map { ($0.name, $0) }, uniquingKeysWith: { first, _ in first })
        jointsByName = Dictionary(joints.map { ($0.name, $0) }, uniquingKeysWith: { first, _ in first })
        jointsByParent = Dictionary(grouping: joints, by: \.parent)
        parentJoint = Dictionary(joints.map { ($0.child, $0) }, uniquingKeysWith: { first, _ in first })

        for joint in joints {
            guard linksByName[joint.parent] != nil else {
                throw URDFParseError.unknownLink(joint.parent, referencedBy: joint.name)
            }
            guard linksByName[joint.child] != nil else {
                throw URDFParseError.unknownLink(joint.child, referencedBy: joint.name)
            }
        }
        let roots = links.map(\.name).filter { parentJoint[$0] == nil }
        guard roots.count == 1, let root = roots.first else {
            throw URDFParseError.notASingleRootedTree(rootCount: roots.count)
        }
        rootLinkName = root
    }

    public func link(named name: String) -> URDFLink? { linksByName[name] }
    public func joint(named name: String) -> URDFJoint? { jointsByName[name] }
    public func childJoints(of link: String) -> [URDFJoint] { jointsByParent[link] ?? [] }

    /// Joints that actually move, in declaration order.
    public var movableJoints: [URDFJoint] {
        joints.filter { $0.kind.isMovable }
    }

    /// Every distinct mesh referenced by a `<visual>`. Collision geometry is never
    /// parsed, so it cannot leak in here and cause needless downloads.
    public var visualMeshFilenames: Set<String> {
        var names: Set<String> = []
        for link in links {
            for visual in link.visuals {
                if case let .mesh(filename, _) = visual.geometry {
                    names.insert(filename)
                }
            }
        }
        return names
    }
}

public struct URDFLink: Sendable, Equatable {
    public let name: String
    public let visuals: [URDFVisual]

    public init(name: String, visuals: [URDFVisual]) {
        self.name = name
        self.visuals = visuals
    }
}

public struct URDFVisual: Sendable, Equatable {
    public let origin: URDFPose
    public let geometry: URDFGeometry
    public let color: URDFColor?

    public init(origin: URDFPose, geometry: URDFGeometry, color: URDFColor?) {
        self.origin = origin
        self.geometry = geometry
        self.color = color
    }
}

public enum URDFGeometry: Sendable, Equatable {
    /// `filename` has the `package://<pkg>/` prefix stripped — it is what the
    /// daemon's STL route expects.
    case mesh(filename: String, scale: SIMD3<Double>)
    case box(size: SIMD3<Double>)
    case cylinder(radius: Double, length: Double)
    case sphere(radius: Double)
}

public struct URDFJoint: Sendable, Equatable {
    public enum Kind: String, Sendable {
        case fixed, revolute, continuous, prismatic, floating, planar

        public var isMovable: Bool {
            switch self {
            case .fixed: false
            default: true
            }
        }
    }

    public let name: String
    public let kind: Kind
    public let parent: String
    public let child: String
    public let origin: URDFPose
    /// Normalised. URDF's default when `<axis>` is absent is (1, 0, 0).
    public let axis: SIMD3<Double>
    public let limit: ClosedRange<Double>?

    public init(
        name: String,
        kind: Kind,
        parent: String,
        child: String,
        origin: URDFPose,
        axis: SIMD3<Double>,
        limit: ClosedRange<Double>?
    ) {
        self.name = name
        self.kind = kind
        self.parent = parent
        self.child = child
        self.origin = origin
        let length = simd_length(axis)
        self.axis = length > 0 ? axis / length : SIMD3(1, 0, 0)
        self.limit = limit
    }
}

/// A frame offset: translation plus roll/pitch/yaw, both in URDF units
/// (metres and radians).
public struct URDFPose: Sendable, Equatable, Hashable {
    public let xyz: SIMD3<Double>
    public let rpy: SIMD3<Double>

    public static let identity = URDFPose(xyz: .zero, rpy: .zero)

    public init(xyz: SIMD3<Double>, rpy: SIMD3<Double>) {
        self.xyz = xyz
        self.rpy = rpy
    }

    public var matrix: simd_double4x4 {
        RigidTransform.transform(translation: xyz, rpy: rpy)
    }
}

public struct URDFColor: Sendable, Equatable, Hashable {
    public let red, green, blue, alpha: Double

    public init(red: Double, green: Double, blue: Double, alpha: Double) {
        self.red = red
        self.green = green
        self.blue = blue
        self.alpha = alpha
    }
}

import Foundation
import simd

public enum URDFParseError: Error, Equatable, LocalizedError {
    case malformedXML(line: Int, column: Int, message: String)
    case missingRobotElement
    case missingAttribute(element: String, attribute: String)
    case unknownJointType(String)
    case unknownLink(String, referencedBy: String)
    case notASingleRootedTree(rootCount: Int)

    public var errorDescription: String? {
        switch self {
        case let .malformedXML(line, column, message):
            "Malformed URDF at \(line):\(column) — \(message)"
        case .missingRobotElement:
            "URDF has no <robot> element"
        case let .missingAttribute(element, attribute):
            "URDF <\(element)> is missing the \(attribute) attribute"
        case let .unknownJointType(type):
            "Unsupported URDF joint type: \(type)"
        case let .unknownLink(link, joint):
            "URDF joint \(joint) references undeclared link \(link)"
        case let .notASingleRootedTree(count):
            "URDF must have exactly one root link, found \(count)"
        }
    }
}

/// Streaming URDF reader.
///
/// `XMLParser` rather than `XMLDocument`: the latter is macOS-only, and this
/// package ships to iOS too. Streaming also avoids building a DOM for a document
/// that is mostly inertia and collision data we discard.
public enum URDFParser {
    public static func parse(_ data: Data) throws -> URDFDocument {
        let delegate = Delegate()
        let parser = XMLParser(data: data)
        parser.delegate = delegate
        guard parser.parse() else {
            if let failure = delegate.failure {
                throw failure
            }
            let error = parser.parserError
            throw URDFParseError.malformedXML(
                line: parser.lineNumber,
                column: parser.columnNumber,
                message: error?.localizedDescription ?? "unknown error"
            )
        }
        if let failure = delegate.failure {
            throw failure
        }
        guard let name = delegate.robotName else {
            throw URDFParseError.missingRobotElement
        }
        return try URDFDocument(name: name, links: delegate.links, joints: delegate.joints)
    }

    public static func parse(_ xml: String) throws -> URDFDocument {
        try parse(Data(xml.utf8))
    }
}

private extension URDFParser {
    /// Mutable scratch state for one link, joint or visual being read.
    struct LinkBuilder {
        var name: String
        var visuals: [URDFVisual] = []
    }

    struct VisualBuilder {
        var origin: URDFPose = .identity
        var geometry: URDFGeometry?
        var color: URDFColor?
    }

    struct JointBuilder {
        var name: String
        var kind: URDFJoint.Kind
        var parent: String?
        var child: String?
        var origin: URDFPose = .identity
        var axis = SIMD3<Double>(1, 0, 0)
        var limit: ClosedRange<Double>?
    }

    final class Delegate: NSObject, XMLParserDelegate {
        var robotName: String?
        var links: [URDFLink] = []
        var joints: [URDFJoint] = []
        var failure: URDFParseError?

        private var link: LinkBuilder?
        private var visual: VisualBuilder?
        private var joint: JointBuilder?
        /// `<collision>` mirrors `<visual>` element for element; skipping the whole
        /// subtree is what keeps collision meshes out of the download list.
        private var skipDepth = 0

        func parser(
            _ parser: XMLParser,
            didStartElement element: String,
            namespaceURI _: String?,
            qualifiedName _: String?,
            attributes: [String: String]
        ) {
            guard failure == nil else { return }
            if skipDepth > 0 {
                skipDepth += 1
                return
            }
            do {
                try start(element, attributes: attributes)
            } catch let error as URDFParseError {
                failure = error
                parser.abortParsing()
            } catch {
                failure = .malformedXML(line: parser.lineNumber, column: parser.columnNumber, message: "\(error)")
                parser.abortParsing()
            }
        }

        func parser(
            _: XMLParser,
            didEndElement element: String,
            namespaceURI _: String?,
            qualifiedName _: String?
        ) {
            guard failure == nil else { return }
            if skipDepth > 0 {
                skipDepth -= 1
                return
            }
            end(element)
        }

        private func start(_ element: String, attributes: [String: String]) throws {
            switch element {
            case "robot":
                robotName = attributes["name"] ?? "robot"
            case "inertial", "collision":
                skipDepth = 1
            case "link":
                link = try LinkBuilder(name: attribute("name", of: element, in: attributes))
            case "visual":
                visual = VisualBuilder()
            case "joint":
                // `<joint>` also appears inside `<transmission>`, where it carries no type.
                guard let name = attributes["name"], let rawType = attributes["type"] else {
                    skipDepth = 1
                    return
                }
                guard let kind = URDFJoint.Kind(rawValue: rawType) else {
                    throw URDFParseError.unknownJointType(rawType)
                }
                joint = JointBuilder(name: name, kind: kind)
            case "origin":
                let pose = URDFPose(
                    xyz: Self.vector(attributes["xyz"]) ?? .zero,
                    rpy: Self.vector(attributes["rpy"]) ?? .zero
                )
                if visual != nil {
                    visual?.origin = pose
                } else {
                    joint?.origin = pose
                }
            case "mesh":
                let filename = try attribute("filename", of: element, in: attributes)
                visual?.geometry = .mesh(
                    filename: Self.strippedPackagePrefix(filename),
                    scale: Self.vector(attributes["scale"]) ?? SIMD3(1, 1, 1)
                )
            case "box":
                visual?.geometry = .box(size: Self.vector(attributes["size"]) ?? .zero)
            case "cylinder":
                visual?.geometry = .cylinder(
                    radius: Self.scalar(attributes["radius"]) ?? 0,
                    length: Self.scalar(attributes["length"]) ?? 0
                )
            case "sphere":
                visual?.geometry = .sphere(radius: Self.scalar(attributes["radius"]) ?? 0)
            case "color":
                visual?.color = Self.color(attributes["rgba"])
            case "parent":
                joint?.parent = attributes["link"]
            case "child":
                joint?.child = attributes["link"]
            case "axis":
                if let axis = Self.vector(attributes["xyz"]) {
                    joint?.axis = axis
                }
            case "limit":
                if let lower = Self.scalar(attributes["lower"]),
                   let upper = Self.scalar(attributes["upper"]), lower <= upper {
                    joint?.limit = lower ... upper
                }
            default:
                break
            }
        }

        private func end(_ element: String) {
            switch element {
            case "visual":
                if let visual, let geometry = visual.geometry {
                    link?.visuals.append(
                        URDFVisual(origin: visual.origin, geometry: geometry, color: visual.color)
                    )
                }
                visual = nil
            case "link":
                if let link {
                    links.append(URDFLink(name: link.name, visuals: link.visuals))
                }
                link = nil
            case "joint":
                if let joint, let parent = joint.parent, let child = joint.child {
                    joints.append(URDFJoint(
                        name: joint.name,
                        kind: joint.kind,
                        parent: parent,
                        child: child,
                        origin: joint.origin,
                        axis: joint.axis,
                        limit: joint.limit
                    ))
                }
                self.joint = nil
            default:
                break
            }
        }

        private func attribute(
            _ name: String,
            of element: String,
            in attributes: [String: String]
        ) throws -> String {
            guard let value = attributes[name] else {
                throw URDFParseError.missingAttribute(element: element, attribute: name)
            }
            return value
        }

        /// `Double(_:)` is locale-independent; `NumberFormatter` is not, and URDF
        /// is always written with a dot.
        private static func numbers(_ raw: String?) -> [Double]? {
            guard let raw else { return nil }
            let parts = raw.split(whereSeparator: \.isWhitespace).compactMap { Double($0) }
            return parts.isEmpty ? nil : parts
        }

        private static func vector(_ raw: String?) -> SIMD3<Double>? {
            guard let values = numbers(raw), values.count >= 3 else { return nil }
            return SIMD3(values[0], values[1], values[2])
        }

        private static func scalar(_ raw: String?) -> Double? {
            numbers(raw)?.first
        }

        private static func color(_ raw: String?) -> URDFColor? {
            guard let values = numbers(raw), values.count >= 4 else { return nil }
            return URDFColor(red: values[0], green: values[1], blue: values[2], alpha: values[3])
        }

        /// `package://assets/base.stl` names the file `base.stl` on the daemon's
        /// STL route; the package segment is meaningless to us.
        private static func strippedPackagePrefix(_ filename: String) -> String {
            guard let range = filename.range(of: "://") else { return filename }
            let afterScheme = filename[range.upperBound...]
            guard let slash = afterScheme.firstIndex(of: "/") else { return String(afterScheme) }
            return String(afterScheme[afterScheme.index(after: slash)...])
        }
    }
}

import Foundation
@testable import ReachyKit
import simd
import Testing

@Suite("URDF parser")
struct URDFParserTests {
    /// Mirrors the shapes the real robot description uses — two links joined by a
    /// revolute joint, a visual with an inline material, and a collision block
    /// that repeats the visual's mesh.
    private static let sample = """
    <?xml version="1.0" ?>
    <robot name="sample">
      <link name="base">
        <inertial>
          <origin xyz="0 0 1" rpy="0 0 0"/>
          <mass value="0.5"/>
        </inertial>
        <visual>
          <origin xyz="0.1 0.2 0.3" rpy="0 0 1.5708"/>
          <geometry><mesh filename="package://assets/base.stl"/></geometry>
          <material name="base_material"><color rgba="0.3 0.3 0.3 1"/></material>
        </visual>
        <collision>
          <origin xyz="9 9 9" rpy="0 0 0"/>
          <geometry><mesh filename="package://assets/base_collider.stl"/></geometry>
        </collision>
      </link>
      <link name="arm">
        <visual>
          <geometry><box size="0.01 0.02 0.03"/></geometry>
        </visual>
      </link>
      <joint name="shoulder" type="revolute">
        <origin xyz="0 0 0.04" rpy="0 0 0"/>
        <parent link="base"/>
        <child link="arm"/>
        <axis xyz="0 0 1"/>
        <limit effort="10" velocity="8" lower="-0.837758" upper="1.39626"/>
      </joint>
    </robot>
    """

    @Test("reads the link and joint tree")
    func tree() throws {
        let urdf = try URDFParser.parse(Self.sample)
        #expect(urdf.name == "sample")
        #expect(urdf.links.count == 2)
        #expect(urdf.joints.count == 1)
        #expect(urdf.rootLinkName == "base")
        #expect(urdf.childJoints(of: "base").map(\.name) == ["shoulder"])
        #expect(urdf.childJoints(of: "arm").isEmpty)
    }

    @Test("reads joint frame, axis and limits")
    func jointDetail() throws {
        let joint = try #require(URDFParser.parse(Self.sample).joint(named: "shoulder"))
        #expect(joint.kind == .revolute)
        #expect(joint.parent == "base")
        #expect(joint.child == "arm")
        #expect(joint.origin.xyz == SIMD3(0, 0, 0.04))
        #expect(joint.axis == SIMD3(0, 0, 1))
        #expect(joint.limit == -0.837758 ... 1.39626)
    }

    /// Collision geometry doubles the mesh count and none of it is ever drawn, so
    /// letting it through would double the download for nothing.
    @Test("collision geometry never reaches the mesh list")
    func collisionIgnored() throws {
        let urdf = try URDFParser.parse(Self.sample)
        #expect(urdf.visualMeshFilenames == ["base.stl"])
        #expect(urdf.link(named: "base")?.visuals.count == 1)
    }

    @Test("package:// prefix is stripped down to the daemon's filename")
    func meshNaming() throws {
        let urdf = try URDFParser.parse(Self.sample)
        let visual = try #require(urdf.link(named: "base")?.visuals.first)
        #expect(visual.geometry == .mesh(filename: "base.stl", scale: SIMD3(1, 1, 1)))
        #expect(visual.color == URDFColor(red: 0.3, green: 0.3, blue: 0.3, alpha: 1))
    }

    /// An inertial `<origin>` sits before the visual one and must not be mistaken
    /// for it — a plain "last origin wins" reader gets this wrong.
    @Test("inertial data does not leak into the visual frame")
    func inertialIgnored() throws {
        let visual = try #require(URDFParser.parse(Self.sample).link(named: "base")?.visuals.first)
        #expect(visual.origin.xyz == SIMD3(0.1, 0.2, 0.3))
        #expect(abs(visual.origin.rpy.z - 1.5708) < 1e-9)
    }

    @Test("a missing origin means identity")
    func defaultOrigin() throws {
        let visual = try #require(URDFParser.parse(Self.sample).link(named: "arm")?.visuals.first)
        #expect(visual.origin == .identity)
        #expect(visual.geometry == .box(size: SIMD3(0.01, 0.02, 0.03)))
    }

    @Test("non-mesh primitives are kept")
    func primitives() throws {
        let urdf = try URDFParser.parse("""
        <robot name="p">
          <link name="a">
            <visual><geometry><cylinder radius="0.5" length="2"/></geometry></visual>
            <visual><geometry><sphere radius="0.25"/></geometry></visual>
          </link>
        </robot>
        """)
        #expect(urdf.link(named: "a")?.visuals.map(\.geometry) == [
            .cylinder(radius: 0.5, length: 2),
            .sphere(radius: 0.25),
        ])
    }

    @Test("movable joints exclude fixed ones")
    func movableJoints() throws {
        let urdf = try URDFParser.parse("""
        <robot name="m">
          <link name="a"/><link name="b"/><link name="c"/>
          <joint name="weld" type="fixed"><parent link="a"/><child link="b"/></joint>
          <joint name="spin" type="continuous"><parent link="b"/><child link="c"/></joint>
        </robot>
        """)
        #expect(urdf.movableJoints.map(\.name) == ["spin"])
        #expect(urdf.joint(named: "spin")?.limit == nil)
    }

    @Test("an unnormalised axis is normalised")
    func axisNormalisation() throws {
        let urdf = try URDFParser.parse("""
        <robot name="n">
          <link name="a"/><link name="b"/>
          <joint name="j" type="revolute">
            <parent link="a"/><child link="b"/><axis xyz="0 0 5"/>
          </joint>
        </robot>
        """)
        #expect(urdf.joint(named: "j")?.axis == SIMD3(0, 0, 1))
    }

    @Test("a joint pointing at an undeclared link is rejected")
    func unknownLink() {
        #expect(throws: URDFParseError.unknownLink("ghost", referencedBy: "j")) {
            try URDFParser.parse("""
            <robot name="x">
              <link name="a"/>
              <joint name="j" type="fixed"><parent link="a"/><child link="ghost"/></joint>
            </robot>
            """)
        }
    }

    @Test("a forest is rejected — the scene needs one root")
    func multipleRoots() {
        #expect(throws: URDFParseError.notASingleRootedTree(rootCount: 2)) {
            try URDFParser.parse(#"<robot name="x"><link name="a"/><link name="b"/></robot>"#)
        }
    }

    @Test("an unsupported joint type is reported by name")
    func unknownJointType() {
        #expect(throws: URDFParseError.unknownJointType("screw")) {
            try URDFParser.parse("""
            <robot name="x">
              <link name="a"/><link name="b"/>
              <joint name="j" type="screw"><parent link="a"/><child link="b"/></joint>
            </robot>
            """)
        }
    }

    @Test("broken XML fails as a parse error, not a crash")
    func malformedXML() {
        #expect(throws: URDFParseError.self) {
            try URDFParser.parse("<robot name=\"x\"><link name=\"a\">")
        }
    }
}

/// Validates the parser against a real robot description without committing one:
/// Pollen's URDF is their asset, and this client deliberately ships no robot
/// geometry. Point `REACHY_URDF_FIXTURE` at a file pulled from a daemon
/// (`GET /api/kinematics/urdf`) to run these.
@Suite(
    "URDF parser against a real description",
    .enabled(if: ProcessInfo.processInfo.environment["REACHY_URDF_FIXTURE"] != nil)
)
struct RealURDFTests {
    private func loadDocument() throws -> URDFDocument {
        let path = try #require(ProcessInfo.processInfo.environment["REACHY_URDF_FIXTURE"])
        return try URDFParser.parse(Data(contentsOf: URL(fileURLWithPath: path)))
    }

    @Test("the Reachy Mini tree has the shape the viewer assumes")
    func shape() throws {
        let urdf = try loadDocument()
        #expect(urdf.links.count == 45)
        #expect(urdf.joints.count == 44)
        #expect(urdf.joints.filter { $0.kind == .revolute }.count == 30)
        #expect(urdf.joints.filter { $0.kind == .fixed }.count == 14)
        #expect(urdf.rootLinkName == "body_foot_3dprint")
    }

    @Test("the nine actuators are present with the axes the solver expects")
    func actuators() throws {
        let urdf = try loadDocument()
        let names = ["yaw_body", "left_antenna", "right_antenna"]
            + (1 ... 6).map { "stewart_\($0)" }
        for name in names {
            let joint = try #require(urdf.joint(named: name), "missing \(name)")
            #expect(joint.axis == SIMD3(0, 0, 1), "\(name) axis")
        }
        #expect(urdf.joint(named: "yaw_body")?.limit == -2.79253 ... 2.79253)
    }

    /// Seven spherical joints, each split into an x-y-z chain because URDF has no
    /// spherical type. Legs 1-5 are cut open and closed by fixed frames; only leg
    /// 6 runs through to the head, which is why there is a seventh.
    @Test("all 21 passive joints are declared as an orthogonal chain")
    func passiveJoints() throws {
        let urdf = try loadDocument()
        let axes: [String: SIMD3<Double>] = [
            "x": SIMD3(1, 0, 0), "y": SIMD3(0, 1, 0), "z": SIMD3(0, 0, 1),
        ]
        for index in 1 ... 7 {
            for (suffix, axis) in axes {
                let joint = try #require(urdf.joint(named: "passive_\(index)_\(suffix)"))
                #expect(joint.kind == .revolute)
                #expect(joint.axis == axis)
            }
        }
    }

    /// The head hangs off leg 6 through both passive wrists, so zeroing the passive
    /// joints moves the head itself — not just the rods.
    @Test("the head link descends from leg 6 through both passive wrists")
    func headChain() throws {
        let urdf = try loadDocument()
        var chain: [String] = []
        var link = "xl_330"
        while let joint = urdf.joints.first(where: { $0.child == link }) {
            chain.append(joint.name)
            link = joint.parent
        }
        #expect(chain.prefix(3) == ["passive_7_z", "passive_7_y", "passive_7_x"])
        #expect(chain.contains("stewart_6"))
        #expect(link == urdf.rootLinkName)
    }

    @Test("visual meshes are far fewer than the asset directory")
    func meshes() throws {
        let urdf = try loadDocument()
        #expect(urdf.visualMeshFilenames.count == 41)
        #expect(urdf.visualMeshFilenames.allSatisfy { $0.hasSuffix(".stl") })
        #expect(urdf.visualMeshFilenames.allSatisfy { !$0.contains("://") })
    }
}

