import Foundation
import simd

/// Triangle soup straight out of an STL file.
///
/// Vertices are deliberately not welded: STL stores one normal per facet, and
/// keeping three separate vertices per triangle preserves the faceted look of a
/// 3D-printed part. Welding would average the normals and turn crisp edges soft.
public struct STLMesh: Sendable, Equatable {
    public let positions: [SIMD3<Float>]
    public let normals: [SIMD3<Float>]
    public let indices: [UInt32]

    public init(positions: [SIMD3<Float>], normals: [SIMD3<Float>], indices: [UInt32]) {
        self.positions = positions
        self.normals = normals
        self.indices = indices
    }

    public var triangleCount: Int { indices.count / 3 }

    public var bounds: (min: SIMD3<Float>, max: SIMD3<Float>)? {
        guard let first = positions.first else { return nil }
        return positions.dropFirst().reduce((first, first)) { box, point in
            (simd_min(box.0, point), simd_max(box.1, point))
        }
    }
}

public enum STLDecodeError: Error, Equatable, LocalizedError {
    case tooShort
    case truncated(expected: Int, actual: Int)
    case malformedASCII(line: Int)
    case empty

    public var errorDescription: String? {
        switch self {
        case .tooShort:
            "STL file is too short to contain a header"
        case let .truncated(expected, actual):
            "STL file is truncated: expected \(expected) bytes, found \(actual)"
        case let .malformedASCII(line):
            "Malformed ASCII STL at line \(line)"
        case .empty:
            "STL file contains no usable triangles"
        }
    }
}

/// Reads both STL flavours.
///
/// Model I/O could do this, but only from a file URL, and it is free to weld
/// vertices — which would cost the faceted shading these parts need. A decoder
/// over `Data` is also a pure function, so it can be tested without a filesystem
/// or a Metal device.
public enum STLDecoder {
    private static let headerSize = 80
    private static let triangleStride = 50

    public static func decode(_ data: Data) throws -> STLMesh {
        guard data.count >= headerSize + 4 else {
            throw STLDecodeError.tooShort
        }
        let mesh = try isBinary(data) ? decodeBinary(data) : decodeASCII(data)
        guard !mesh.indices.isEmpty else {
            throw STLDecodeError.empty
        }
        return mesh
    }

    /// Not decided by a leading "solid": plenty of exporters write that word into
    /// a binary file's 80-byte header. The declared triangle count matching the
    /// file length is the only reliable signal.
    private static func isBinary(_ data: Data) -> Bool {
        let count = data.withUnsafeBytes { raw in
            Int(raw.loadUnaligned(fromByteOffset: headerSize, as: UInt32.self).littleEndian)
        }
        return data.count == headerSize + 4 + count * triangleStride
    }

    private static func decodeBinary(_ data: Data) throws -> STLMesh {
        let count = data.withUnsafeBytes { raw in
            Int(raw.loadUnaligned(fromByteOffset: headerSize, as: UInt32.self).littleEndian)
        }
        let expected = headerSize + 4 + count * triangleStride
        guard data.count >= expected else {
            throw STLDecodeError.truncated(expected: expected, actual: data.count)
        }

        var builder = Builder(capacity: count)
        data.withUnsafeBytes { raw in
            for triangle in 0 ..< count {
                let base = headerSize + 4 + triangle * triangleStride
                // Offsets are not four-byte aligned once the 84-byte prologue is
                // passed, so an aligned load would trap on arm64.
                func float(_ index: Int) -> Float {
                    Float(bitPattern: raw.loadUnaligned(
                        fromByteOffset: base + index * 4,
                        as: UInt32.self
                    ).littleEndian)
                }
                builder.add(
                    normal: SIMD3(float(0), float(1), float(2)),
                    corners: (
                        SIMD3(float(3), float(4), float(5)),
                        SIMD3(float(6), float(7), float(8)),
                        SIMD3(float(9), float(10), float(11))
                    )
                )
            }
        }
        return builder.finish()
    }

    private static func decodeASCII(_ data: Data) throws -> STLMesh {
        guard let text = String(data: data, encoding: .utf8) else {
            throw STLDecodeError.malformedASCII(line: 0)
        }
        var builder = Builder(capacity: 0)
        var normal = SIMD3<Float>.zero
        var corners: [SIMD3<Float>] = []

        for (offset, rawLine) in text.split(separator: "\n", omittingEmptySubsequences: false).enumerated() {
            let fields = rawLine.split(whereSeparator: \.isWhitespace)
            guard let keyword = fields.first else { continue }
            switch keyword {
            case "facet":
                normal = Self.vector(fields.dropFirst(2)) ?? .zero
                corners.removeAll(keepingCapacity: true)
            case "vertex":
                guard let point = Self.vector(fields.dropFirst()) else {
                    throw STLDecodeError.malformedASCII(line: offset + 1)
                }
                corners.append(point)
            case "endfacet":
                guard corners.count == 3 else {
                    throw STLDecodeError.malformedASCII(line: offset + 1)
                }
                builder.add(normal: normal, corners: (corners[0], corners[1], corners[2]))
            default:
                continue
            }
        }
        return builder.finish()
    }

    private static func vector(_ fields: some Collection<Substring>) -> SIMD3<Float>? {
        let values = fields.compactMap { Float($0) }
        guard values.count >= 3 else { return nil }
        return SIMD3(values[0], values[1], values[2])
    }

    /// Accumulates triangles, repairing normals and dropping degenerate facets.
    private struct Builder {
        private var positions: [SIMD3<Float>] = []
        private var normals: [SIMD3<Float>] = []
        private var indices: [UInt32] = []

        init(capacity: Int) {
            positions.reserveCapacity(capacity * 3)
            normals.reserveCapacity(capacity * 3)
            indices.reserveCapacity(capacity * 3)
        }

        mutating func add(
            normal: SIMD3<Float>,
            corners: (SIMD3<Float>, SIMD3<Float>, SIMD3<Float>)
        ) {
            // A zero normal is legal in the format and means "work it out";
            // an unnormalised one makes RealityKit's lighting misbehave.
            let geometric = simd_cross(corners.1 - corners.0, corners.2 - corners.0)
            let resolved = simd_length(normal) > 1e-12 ? normal : geometric
            guard simd_length(resolved) > 1e-12 else {
                return // Degenerate facet: zero area, nothing to shade.
            }
            let unit = simd_normalize(resolved)
            let base = UInt32(positions.count)
            positions.append(contentsOf: [corners.0, corners.1, corners.2])
            normals.append(contentsOf: [unit, unit, unit])
            indices.append(contentsOf: [base, base + 1, base + 2])
        }

        func finish() -> STLMesh {
            STLMesh(positions: positions, normals: normals, indices: indices)
        }
    }
}

import Foundation
@testable import ReachyKit
import simd
import Testing

@Suite("STL decoding")
struct STLDecoderTests {
    /// Builds a binary STL by hand so the fixtures stay in the test and no robot
    /// geometry has to be committed.
    private static func binarySTL(
        header: String = "test",
        triangles: [(normal: SIMD3<Float>, corners: [SIMD3<Float>])]
    ) -> Data {
        var data = Data(count: 80)
        data.replaceSubrange(0 ..< min(header.utf8.count, 80), with: Array(header.utf8))
        withUnsafeBytes(of: UInt32(triangles.count).littleEndian) { data.append(contentsOf: $0) }
        for triangle in triangles {
            for value in [triangle.normal] + triangle.corners {
                for component in [value.x, value.y, value.z] {
                    withUnsafeBytes(of: component.bitPattern.littleEndian) { data.append(contentsOf: $0) }
                }
            }
            data.append(contentsOf: [0, 0]) // attribute byte count
        }
        return data
    }

    private static let unitTriangle: (normal: SIMD3<Float>, corners: [SIMD3<Float>]) = (
        normal: SIMD3(0, 0, 1),
        corners: [SIMD3(0, 0, 0), SIMD3(1, 0, 0), SIMD3(0, 1, 0)]
    )

    @Test("reads a binary triangle")
    func binaryTriangle() throws {
        let mesh = try STLDecoder.decode(Self.binarySTL(triangles: [Self.unitTriangle]))
        #expect(mesh.triangleCount == 1)
        #expect(mesh.positions == Self.unitTriangle.corners)
        #expect(mesh.normals == Array(repeating: SIMD3(0, 0, 1), count: 3))
        #expect(mesh.indices == [0, 1, 2])
    }

    /// Exporters routinely write "solid" into a binary header, so sniffing the
    /// prefix misidentifies the file. The length check is what actually decides.
    @Test("a binary file whose header starts with 'solid' is still binary")
    func binaryWithSolidHeader() throws {
        let mesh = try STLDecoder.decode(Self.binarySTL(header: "solid cad-export", triangles: [Self.unitTriangle]))
        #expect(mesh.triangleCount == 1)
    }

    @Test("reads an ASCII triangle")
    func asciiTriangle() throws {
        let text = """
        solid model
          facet normal 0 0 1
            outer loop
              vertex 0 0 0
              vertex 1 0 0
              vertex 0 1 0
            endloop
          endfacet
        endsolid model
        """
        let mesh = try STLDecoder.decode(Data(text.utf8))
        #expect(mesh.triangleCount == 1)
        #expect(mesh.positions.last == SIMD3(0, 1, 0))
    }

    @Test("a zero normal is recomputed from the winding")
    func zeroNormalRepaired() throws {
        let triangle = (normal: SIMD3<Float>.zero, corners: Self.unitTriangle.corners)
        let mesh = try STLDecoder.decode(Self.binarySTL(triangles: [triangle]))
        #expect(mesh.normals.allSatisfy { simd_length($0 - SIMD3(0, 0, 1)) < 1e-6 })
    }

    @Test("an unnormalised normal is normalised")
    func normalIsUnitLength() throws {
        let triangle = (normal: SIMD3<Float>(0, 0, 7), corners: Self.unitTriangle.corners)
        let mesh = try STLDecoder.decode(Self.binarySTL(triangles: [triangle]))
        #expect(mesh.normals.allSatisfy { abs(simd_length($0) - 1) < 1e-6 })
    }

    @Test("a zero-area facet is dropped rather than shaded")
    func degenerateDropped() throws {
        let flat = (
            normal: SIMD3<Float>.zero,
            corners: [SIMD3<Float>(1, 1, 1), SIMD3<Float>(1, 1, 1), SIMD3<Float>(1, 1, 1)]
        )
        #expect(throws: STLDecodeError.empty) {
            try STLDecoder.decode(Self.binarySTL(triangles: [flat]))
        }
        let mesh = try STLDecoder.decode(Self.binarySTL(triangles: [flat, Self.unitTriangle]))
        #expect(mesh.triangleCount == 1)
    }

    @Test("a truncated binary file is reported, not read past the end")
    func truncated() {
        var data = Self.binarySTL(triangles: [Self.unitTriangle, Self.unitTriangle])
        data.removeLast(20)
        #expect(throws: STLDecodeError.self) {
            try STLDecoder.decode(data)
        }
    }

    @Test("a file too short for a header is rejected")
    func tooShort() {
        #expect(throws: STLDecodeError.tooShort) {
            try STLDecoder.decode(Data(count: 10))
        }
    }

    @Test("bounds cover every vertex")
    func bounds() throws {
        let mesh = try STLDecoder.decode(Self.binarySTL(triangles: [Self.unitTriangle]))
        let bounds = try #require(mesh.bounds)
        #expect(bounds.min == SIMD3(0, 0, 0))
        #expect(bounds.max == SIMD3(1, 1, 0))
    }

    /// Three vertices per triangle even when they coincide — welding them would
    /// average the facet normals and soften the printed edges.
    @Test("shared corners are not welded")
    func noVertexWelding() throws {
        let second = (
            normal: SIMD3<Float>(0, 1, 0),
            corners: [SIMD3<Float>(0, 0, 0), SIMD3<Float>(1, 0, 0), SIMD3<Float>(0, 0, 1)]
        )
        let mesh = try STLDecoder.decode(Self.binarySTL(triangles: [Self.unitTriangle, second]))
        #expect(mesh.positions.count == 6)
        #expect(mesh.indices == [0, 1, 2, 3, 4, 5])
    }
}

import CryptoKit
import Foundation

/// On-disk store for one robot's URDF and meshes.
///
/// Entries are keyed by a digest of the URDF text rather than by robot identity
/// or daemon version. A hardware id is null on the simulator, and the daemon
/// version does not change when the description does — but the digest changes
/// exactly when the geometry does, so staleness cannot happen.
///
/// Everything here is recoverable from the robot, which is why it lives in
/// `Caches` and may be evicted by the system at any time.
public struct GeometryCache: Sendable {
    private let root: URL
    private let fileManager = FileManager.default

    public init(root: URL) {
        self.root = root
    }

    public static var `default`: GeometryCache {
        let caches = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask).first
            ?? URL(fileURLWithPath: NSTemporaryDirectory())
        return GeometryCache(root: caches.appendingPathComponent("ReachyMini/geometry", isDirectory: true))
    }

    public static func digest(of urdf: String) -> String {
        SHA256.hash(data: Data(urdf.utf8)).map { String(format: "%02x", $0) }.joined()
    }

    // MARK: - Layout

    private func directory(for digest: String) -> URL {
        root.appendingPathComponent(digest, isDirectory: true)
    }

    private func urdfURL(for digest: String) -> URL {
        directory(for: digest).appendingPathComponent("robot.urdf")
    }

    private func meshURL(for digest: String, mesh: String) -> URL {
        directory(for: digest)
            .appendingPathComponent("meshes", isDirectory: true)
            .appendingPathComponent(mesh)
    }

    /// Written last, so its presence means the entry is complete. Without it a
    /// download interrupted halfway would look like a usable cache.
    private func manifestURL(for digest: String) -> URL {
        directory(for: digest).appendingPathComponent("manifest.json")
    }

    // MARK: - Reading

    public func isComplete(digest: String) -> Bool {
        fileManager.fileExists(atPath: manifestURL(for: digest).path)
    }

    public func storedURDF(digest: String) -> String? {
        try? String(contentsOf: urdfURL(for: digest), encoding: .utf8)
    }

    public func storedMesh(digest: String, named mesh: String) -> Data? {
        try? Data(contentsOf: meshURL(for: digest, mesh: mesh))
    }

    // MARK: - Writing

    public func store(urdf: String, digest: String) throws {
        try fileManager.createDirectory(
            at: directory(for: digest).appendingPathComponent("meshes", isDirectory: true),
            withIntermediateDirectories: true
        )
        try write(Data(urdf.utf8), to: urdfURL(for: digest))
    }

    public func store(mesh: Data, digest: String, named name: String) throws {
        try write(mesh, to: meshURL(for: digest, mesh: name))
    }

    public func finalize(digest: String, meshes: [String]) throws {
        try write(JSONEncoder().encode(meshes.sorted()), to: manifestURL(for: digest))
    }

    /// Replaces atomically: a partial file left by a cancelled download would
    /// otherwise survive restarts and decode into garbage.
    private func write(_ data: Data, to url: URL) throws {
        try fileManager.createDirectory(
            at: url.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )
        try data.write(to: url, options: .atomic)
    }

    /// Drops every entry other than the one in use.
    public func removeEntries(keeping digest: String) {
        guard let entries = try? fileManager.contentsOfDirectory(
            at: root,
            includingPropertiesForKeys: nil
        ) else { return }
        for entry in entries where entry.lastPathComponent != digest {
            try? fileManager.removeItem(at: entry)
        }
    }
}

import Foundation

/// A robot description plus every mesh it draws.
public struct RobotGeometry: Sendable {
    public let urdf: URDFDocument
    public let digest: String
    public let meshes: [String: STLMesh]

    public init(urdf: URDFDocument, digest: String, meshes: [String: STLMesh]) {
        self.urdf = urdf
        self.digest = digest
        self.meshes = meshes
    }
}

public enum GeometryLoadProgress: Sendable, Equatable {
    case fetchingDescription
    case downloadingMeshes(completed: Int, total: Int)
    case ready(RobotGeometry)

    public static func == (lhs: Self, rhs: Self) -> Bool {
        switch (lhs, rhs) {
        case (.fetchingDescription, .fetchingDescription):
            true
        case let (.downloadingMeshes(a, b), .downloadingMeshes(c, d)):
            a == c && b == d
        case let (.ready(lhs), .ready(rhs)):
            lhs.digest == rhs.digest
        default:
            false
        }
    }
}

/// Fetches the robot's own geometry and keeps a copy on disk.
///
/// Nothing is bundled with the app: the description comes from the machine in
/// front of the user, so a hardware revision or a differently coloured shell is
/// drawn correctly without shipping anyone else's assets.
public actor RobotGeometryProvider {
    private let client: any RobotAPIClient
    private let cache: GeometryCache
    /// The robot's Wi-Fi is the slow link here; a handful of parallel requests
    /// saturates it without starving the state stream sharing the connection.
    private let concurrentDownloads = 4

    public init(client: any RobotAPIClient, cache: GeometryCache = .default) {
        self.client = client
        self.cache = cache
    }

    public func load() -> AsyncThrowingStream<GeometryLoadProgress, any Error> {
        AsyncThrowingStream { continuation in
            let task = Task {
                do {
                    try await self.run(reporting: continuation)
                    continuation.finish()
                } catch {
                    continuation.finish(throwing: error)
                }
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }

    private func run(
        reporting continuation: AsyncThrowingStream<GeometryLoadProgress, any Error>.Continuation
    ) async throws {
        continuation.yield(.fetchingDescription)
        let xml = try await client.urdf()
        let digest = GeometryCache.digest(of: xml)
        let document = try URDFParser.parse(xml)
        try cache.store(urdf: xml, digest: digest)

        let wanted = document.visualMeshFilenames.sorted()
        var meshes: [String: STLMesh] = [:]
        var completed = 0
        continuation.yield(.downloadingMeshes(completed: 0, total: wanted.count))

        for chunk in wanted.chunked(into: concurrentDownloads) {
            try Task.checkCancellation()
            let loaded = try await withThrowingTaskGroup(of: (String, STLMesh).self) { group in
                for name in chunk {
                    group.addTask { try await (name, self.mesh(named: name, digest: digest)) }
                }
                return try await group.reduce(into: [String: STLMesh]()) { $0[$1.0] = $1.1 }
            }
            meshes.merge(loaded) { _, new in new }
            completed += chunk.count
            continuation.yield(.downloadingMeshes(completed: completed, total: wanted.count))
        }

        try cache.finalize(digest: digest, meshes: wanted)
        cache.removeEntries(keeping: digest)
        continuation.yield(.ready(RobotGeometry(urdf: document, digest: digest, meshes: meshes)))
    }

    private func mesh(named name: String, digest: String) async throws -> STLMesh {
        if let cached = cache.storedMesh(digest: digest, named: name),
           let mesh = try? STLDecoder.decode(cached) {
            return mesh
        }
        let data = try await client.stlAsset(named: name)
        let mesh = try STLDecoder.decode(data)
        // Only cache what decoded: a corrupt download must not become a permanent
        // cache entry that fails identically on every launch.
        try? cache.store(mesh: data, digest: digest, named: name)
        return mesh
    }
}

extension Array {
    func chunked(into size: Int) -> [[Element]] {
        guard size > 0 else { return [self] }
        return stride(from: 0, to: count, by: size).map {
            Array(self[$0 ..< Swift.min($0 + size, count)])
        }
    }
}

