import Foundation

/// Every joint angle the viewer needs, addressed by its URDF name.
public struct RobotJointState: Sendable, Equatable {
    /// Drives `yaw_body`.
    public var bodyYaw: Double = 0
    /// Six values for `stewart_1` ... `stewart_6`.
    public var stewart: [Double] = Array(repeating: 0, count: 6)
    public var antennaLeft: Double = 0
    public var antennaRight: Double = 0
    /// Twenty-one values: `passive_1_x` ... `passive_7_z`.
    public var passive: [Double] = Array(repeating: 0, count: 21)

    public static let neutral = RobotJointState()

    public init() {}

    public subscript(jointName: String) -> Double? {
        switch jointName {
        case "yaw_body": bodyYaw
        case "left_antenna": antennaLeft
        case "right_antenna": antennaRight
        default: indexed(jointName)
        }
    }

    private func indexed(_ jointName: String) -> Double? {
        if let index = Self.stewartIndex(jointName) {
            return stewart.indices.contains(index) ? stewart[index] : nil
        }
        if let index = Self.passiveIndex(jointName) {
            return passive.indices.contains(index) ? passive[index] : nil
        }
        return nil
    }

    /// `stewart_1` ... `stewart_6`, one-based in the URDF.
    private static func stewartIndex(_ name: String) -> Int? {
        guard name.hasPrefix("stewart_"), let number = Int(name.dropFirst(8)) else { return nil }
        return number - 1
    }

    /// `passive_<1...7>_<x|y|z>` flattens to `(chain - 1) * 3 + axis`.
    private static func passiveIndex(_ name: String) -> Int? {
        guard name.hasPrefix("passive_") else { return nil }
        let parts = name.dropFirst(8).split(separator: "_")
        guard parts.count == 2, let chain = Int(parts[0]) else { return nil }
        let axis: Int
        switch parts[1] {
        case "x": axis = 0
        case "y": axis = 1
        case "z": axis = 2
        default: return nil
        }
        return (chain - 1) * 3 + axis
    }

    /// Builds a pose from one state-stream frame.
    ///
    /// `head_joints` carries `[body_yaw, stewart_1 ... stewart_6]` and is the
    /// preferred source; `body_yaw` alone is the fallback for streams that did not
    /// ask for the motor angles.
    public static func resolve(_ frame: RobotStateFrame) -> RobotJointState {
        var state = RobotJointState()
        if let joints = frame.headJoints, joints.count >= 7 {
            state.bodyYaw = joints[0]
            state.stewart = Array(joints[1 ... 6])
        } else if let bodyYaw = frame.bodyYaw {
            state.bodyYaw = bodyYaw
        }
        if let antennas = frame.antennas, antennas.count >= 2 {
            // The stream reports (left, right), but the URDF's antenna joints are
            // mirrored and wound the other way, so the pair is crossed and negated.
            // Matches the official viewer; worth re-checking against real hardware
            // if the antennas ever look swapped.
            state.antennaLeft = -antennas[1]
            state.antennaRight = -antennas[0]
        }
        if let passive = frame.passiveJoints, passive.count == 21 {
            state.passive = passive
        }
        return state
    }
}

import ReachyKit
import RealityKit

enum MeshResourceFactory {
    /// `MeshResource.init(from:)` is `nonisolated` from iOS 18 / macOS 15 onwards,
    /// so the 41 meshes of a Reachy Mini are built off the main actor and the UI
    /// never stalls behind them.
    static func make(_ mesh: STLMesh, named name: String) async throws -> MeshResource {
        var descriptor = MeshDescriptor(name: name)
        descriptor.positions = MeshBuffers.Positions(mesh.positions)
        descriptor.normals = MeshBuffers.Normals(mesh.normals)
        descriptor.primitives = .triangles(mesh.indices)
        return try await MeshResource(from: [descriptor])
    }

    /// Builds every mesh once; the URDF references some of them from several
    /// links, and they are shared rather than duplicated.
    static func makeAll(_ meshes: [String: STLMesh]) async -> [String: MeshResource] {
        await withTaskGroup(of: (String, MeshResource)?.self) { group in
            for (name, mesh) in meshes {
                group.addTask {
                    guard let resource = try? await make(mesh, named: name) else { return nil }
                    return (name, resource)
                }
            }
            var built: [String: MeshResource] = [:]
            for await entry in group {
                if let entry {
                    built[entry.0] = entry.1
                }
            }
            return built
        }
    }
}

import Foundation
import ReachyKit
import RealityKit
import simd

/// The robot as a RealityKit entity tree, with a fast path for re-posing it.
///
/// Built once from the URDF; after that only transforms change. Meshes and
/// materials are never rebuilt, which is what makes a 20 Hz update cheap.
@MainActor
public final class RobotSceneGraph {
    /// Carries the URDF's Z-up convention into RealityKit's Y-up world.
    public let root = Entity()

    private var linkEntities: [String: Entity] = [:]
    private var articulations: [Articulation] = []

    /// One movable joint, with its fixed frame pre-split so posing is a single
    /// quaternion multiply.
    private struct Articulation {
        let entity: Entity
        let jointName: String
        let originTranslation: SIMD3<Float>
        let originRotation: simd_quatf
        let axis: SIMD3<Float>
    }

    public init(urdf: URDFDocument, meshes: [String: MeshResource]) {
        root.name = "robot"
        root.transform = Transform(rotation: simd_quatf(angle: -.pi / 2, axis: SIMD3(1, 0, 0)))
        let base = buildLink(named: urdf.rootLinkName, urdf: urdf, meshes: meshes)
        root.addChild(base)
    }

    public func entity(forLink name: String) -> Entity? {
        linkEntities[name]
    }

    public var movableJointNames: [String] {
        articulations.map(\.jointName)
    }

    /// Applies a pose. Joints the state does not mention keep their current angle,
    /// so a partial frame never snaps the robot to zero.
    public func apply(_ state: RobotJointState) {
        for articulation in articulations {
            guard let angle = state[articulation.jointName] else { continue }
            articulation.entity.transform = Transform(
                scale: .one,
                rotation: articulation.originRotation
                    * simd_quatf(angle: Float(angle), axis: articulation.axis),
                translation: articulation.originTranslation
            )
        }
    }

    private func buildLink(
        named name: String,
        urdf: URDFDocument,
        meshes: [String: MeshResource]
    ) -> Entity {
        let entity = Entity()
        entity.name = name
        linkEntities[name] = entity

        if let link = urdf.link(named: name) {
            for visual in link.visuals {
                if let model = makeVisual(visual, meshes: meshes) {
                    entity.addChild(model)
                }
            }
        }

        for joint in urdf.childJoints(of: name) {
            let child = buildLink(named: joint.child, urdf: urdf, meshes: meshes)
            attach(child, with: joint)
            entity.addChild(child)
        }
        return entity
    }

    private func attach(_ child: Entity, with joint: URDFJoint) {
        let origin = Transform(matrix: simd_float4x4(joint.origin.matrix))
        child.transform = origin
        guard joint.kind.isMovable else { return }
        articulations.append(Articulation(
            entity: child,
            jointName: joint.name,
            originTranslation: origin.translation,
            originRotation: origin.rotation,
            axis: SIMD3<Float>(joint.axis)
        ))
    }

    private func makeVisual(
        _ visual: URDFVisual,
        meshes: [String: MeshResource]
    ) -> ModelEntity? {
        guard case let .mesh(filename, _) = visual.geometry,
              let mesh = meshes[filename] else { return nil }
        let color = visual.color ?? URDFColor(red: 0.6, green: 0.6, blue: 0.6, alpha: 1)
        let material = SimpleMaterial(
            color: .init(
                red: CGFloat(color.red),
                green: CGFloat(color.green),
                blue: CGFloat(color.blue),
                alpha: CGFloat(color.alpha)
            ),
            roughness: 0.45,
            isMetallic: false
        )
        let model = ModelEntity(mesh: mesh, materials: [material])
        model.transform = Transform(matrix: simd_float4x4(visual.origin.matrix))
        return model
    }
}

private extension simd_float4x4 {
    init(_ matrix: simd_double4x4) {
        self.init(
            SIMD4<Float>(matrix.columns.0),
            SIMD4<Float>(matrix.columns.1),
            SIMD4<Float>(matrix.columns.2),
            SIMD4<Float>(matrix.columns.3)
        )
    }
}

