@Suite(
    "Stewart geometry probe",
    .enabled(if: ProcessInfo.processInfo.environment["REACHY_URDF_PROBE"] != nil)
)
struct StewartGeometryProbe {
    private func document() throws -> URDFDocument {
        let path = try #require(ProcessInfo.processInfo.environment["REACHY_URDF_FIXTURE"])
        return try URDFParser.parse(Data(contentsOf: URL(fileURLWithPath: path)))
    }

    private func polar(_ point: SIMD3<Double>) -> String {
        let radius = sqrt(point.x * point.x + point.y * point.y)
        let angle = atan2(point.y, point.x) * 180 / .pi
        return String(format: "r=%.6f θ=%+8.3f° z=%.7f", radius, angle, point.z)
    }

    @Test("motor frames")
    func motorFrames() throws {
        let urdf = try document()
        for index in 1 ... 6 {
            guard let joint = urdf.joint(named: "stewart_\(index)"),
                  let fromRoot = urdf.restTransformFromRoot(joint.child),
                  let fromBody = urdf.restTransform(from: "body_down_3dprint", to: joint.child)
            else { continue }
            Issue.record("""
            stewart_\(index): root \(polar(fromRoot.translation)) | body \(polar(fromBody.translation))
