import Foundation
import simd

/// Dimensions of the head's 6-RSS Stewart platform, read out of the robot's own
/// description.
///
/// Every value here also exists as a literal in upstream's kinematics data, but
/// deriving them keeps the client honest: a robot whose geometry differs — a new
/// hardware revision, a different shell — is drawn from its own numbers rather
/// than from ours. `StewartGeometryTests` pins the derivation against the known
/// dimensions so a change in either would be caught.
public struct StewartGeometry: Sendable {
    /// Six motor frames in the base link's frame, each already carrying the crank's
    /// vertical rise so the arm is a plain `[armLength, 0, 0]` in motor space.
    public let motorFrames: [simd_double4x4]
    /// Where each rod meets the platform, in the frame the daemon's head pose uses.
    public let branchPositions: [SIMD3<Double>]
    /// `rpy` of every `passive_i_x` joint: the rest orientation of each spherical
    /// wrist, seven in all.
    public let passiveOffsets: [SIMD3<Double>]
    /// Direction each rod points in its own wrist frame. Not axis-aligned for
    /// every leg — leg 2's mount is rotated.
    public let rodDirections: [SIMD3<Double>]
    public let armLength: Double
    /// The head pose is measured from the head's rest height, so this is added
    /// before solving.
    public let headHeightOffset: Double
    /// Rest transform from the pose's frame to the link the meshes hang off.
    public let headToDrawnLink: simd_double4x4

    public static let legCount = 6
    public static let passiveChainCount = 7

    public init?(urdf: URDFDocument) {
        var motorFrames: [simd_double4x4] = []
        var rodDirections: [SIMD3<Double>] = []
        var branchPositions: [SIMD3<Double>] = []
        var passiveOffsets: [SIMD3<Double>] = []
        var armLength: Double?

        for leg in 1 ... Self.legCount {
            guard let motor = urdf.joint(named: "stewart_\(leg)"),
                  let wrist = urdf.joint(named: "passive_\(leg)_x"),
                  let horn = urdf.restTransformFromRoot(motor.child),
                  let rod = Self.rodDirection(urdf: urdf, leg: leg),
                  let branch = Self.branchPosition(urdf: urdf, leg: leg) else { return nil }

            let crankRise = RigidTransform.transform(
                translation: SIMD3(0, 0, wrist.origin.xyz.z),
                rpy: .zero
            )
            motorFrames.append(horn * crankRise)
            rodDirections.append(rod)
            branchPositions.append(branch)
            armLength = armLength ?? simd_length(SIMD2(wrist.origin.xyz.x, wrist.origin.xyz.y))
        }

        for chain in 1 ... Self.passiveChainCount {
            guard let joint = urdf.joint(named: "passive_\(chain)_x") else { return nil }
            passiveOffsets.append(joint.origin.rpy)
        }

        guard let armLength,
              let head = urdf.restTransformFromRoot("head"),
              let headToDrawnLink = urdf.restTransform(from: "head", to: "xl_330") else { return nil }

        self.motorFrames = motorFrames
        self.branchPositions = branchPositions
        self.passiveOffsets = passiveOffsets
        self.rodDirections = rodDirections
        self.armLength = armLength
        headHeightOffset = head.translation.z
        self.headToDrawnLink = headToDrawnLink
    }

    /// Legs 1-5 end at a `closing_i_1` frame that closes the loop; leg 6 runs on
    /// through the seventh wrist to the head, so its rod is measured from there.
    private static func rodDirection(urdf: URDFDocument, leg: Int) -> SIMD3<Double>? {
        let joint = leg < legCount
            ? urdf.joints.first { $0.child == "closing_\(leg)_1" }
            : urdf.joint(named: "passive_\(passiveChainCount)_x")
        guard let offset = joint?.origin.xyz, simd_length(offset) > 0 else { return nil }
        return simd_normalize(offset)
    }

    /// Same asymmetry on the platform side: five closing frames, and the sixth
    /// point is the seventh wrist itself.
    private static func branchPosition(urdf: URDFDocument, leg: Int) -> SIMD3<Double>? {
        let target = leg < legCount ? "closing_\(leg)_2" : "passive_\(passiveChainCount)_link_x"
        return urdf.restTransform(from: "head", to: target)?.translation
    }
}

import Foundation
import simd

/// Works out the 21 passive joint angles of the head's Stewart platform.
///
/// The daemon reports them only under the Placo engine, and ships with the
/// analytical one, so a client that wants to draw the linkage has to fill the gap
/// itself. This is not inverse kinematics: the head pose and the six motor angles
/// are both known, and what remains is the orientation each rod must take to span
/// the gap between its crank tip and its mount on the platform. The loop is never
/// closed and the rod length never enforced — for a viewer, pointing each rod the
/// right way is enough, and any residual is far below a pixel.
public struct PassiveJointSolver: Sendable {
    private let geometry: StewartGeometry

    public init(geometry: StewartGeometry) {
        self.geometry = geometry
    }

    /// - Parameters:
    ///   - headPose: from the state stream, in the base frame.
    ///   - bodyYaw: removed first, so the rest of the work happens in the frame the
    ///     platform's constants are written in.
    ///   - stewart: the six motor angles.
    public func solve(
        headPose: simd_double4x4,
        bodyYaw: Double,
        stewart: [Double]
    ) -> [Double] {
        guard stewart.count >= StewartGeometry.legCount else {
            return Array(repeating: 0, count: StewartGeometry.passiveChainCount * 3)
        }
        var pose = headPose
        pose.columns.3.z += geometry.headHeightOffset
        pose = RigidTransform.transform(
            rotation: RigidTransform.rotation(rpy: SIMD3(0, 0, -bodyYaw)),
            translation: .zero
        ) * pose

        var angles: [Double] = []
        angles.reserveCapacity(StewartGeometry.passiveChainCount * 3)
        var lastWrist: (frame: simd_double3x3, rotation: simd_double3x3)?

        for leg in 0 ..< StewartGeometry.legCount {
            let solved = solveLeg(leg, pose: pose, angle: stewart[leg])
            angles.append(contentsOf: [solved.euler.x, solved.euler.y, solved.euler.z])
            lastWrist = (solved.wristFrame, solved.rodRotation)
        }

        angles.append(contentsOf: headWrist(pose: pose, lastWrist: lastWrist))
        return angles
    }

    private struct SolvedLeg {
        let euler: SIMD3<Double>
        let wristFrame: simd_double3x3
        let rodRotation: simd_double3x3
    }

    private func solveLeg(_ leg: Int, pose: simd_double4x4, angle: Double) -> SolvedLeg {
        let motor = geometry.motorFrames[leg]
        let crank = RigidTransform.rotation(rpy: SIMD3(0, 0, angle))

        // Where this rod has to reach: its mount on the platform, carried by the pose.
        let mount = pose.rotation * geometry.branchPositions[leg] + pose.translation
        // Where it starts: the tip of the crank, swung by the motor angle.
        let armInMotor = crank * SIMD3(geometry.armLength, 0, 0)
        let tip = (motor * SIMD4(armInMotor, 1)).xyz

        // The wrist sits on the crank, already turned to its rest orientation.
        let wristFrame = motor.rotation * crank
            * RigidTransform.rotation(rpy: geometry.passiveOffsets[leg])
        let span = mount - tip
        guard simd_length(span) > 1e-12 else {
            return SolvedLeg(euler: .zero, wristFrame: wristFrame, rotation: matrix_identity_double3x3)
        }
        let direction = simd_normalize(wristFrame.transpose * span)
        let rodRotation = RigidTransform.alignment(from: geometry.rodDirections[leg], to: direction)
        return SolvedLeg(
            euler: RigidTransform.euler(from: rodRotation),
            wristFrame: wristFrame,
            rodRotation: rodRotation
        )
    }

    /// The seventh wrist joins leg 6's rod to the head, so its angles are whatever
    /// is left between the rod's orientation and the head's.
    private func headWrist(
        pose: simd_double4x4,
        lastWrist: (frame: simd_double3x3, rotation: simd_double3x3)?
    ) -> [Double] {
        guard let lastWrist else { return [0, 0, 0] }
        let head = pose.rotation * geometry.headToDrawnLink.rotation
        let rod = lastWrist.frame * lastWrist.rotation
            * RigidTransform.rotation(rpy: geometry.passiveOffsets[StewartGeometry.legCount])
        let euler = RigidTransform.euler(from: rod.transpose * head)
        return [euler.x, euler.y, euler.z]
    }
}

private extension PassiveJointSolver.SolvedLeg {
    init(euler: SIMD3<Double>, wristFrame: simd_double3x3, rotation: simd_double3x3) {
        self.init(euler: euler, wristFrame: wristFrame, rodRotation: rotation)
    }
}

input.new_string:
return SolvedLeg(
    euler: .zero,
    wristFrame: wristFrame,
    rodRotation: matrix_identity_double3x3
)

