import ReachyScene
import SwiftUI

/// The 3D robot inside the viewport. Read-only: it mirrors the state stream and
/// never sends a command.
struct SceneViewport: View {
    let model: RobotSceneModel

    var body: some View {
        RobotSceneView(model: model)
            .overlay(alignment: .center) { status }
            .overlay(alignment: .topTrailing) { options }
    }

    @ViewBuilder
    private var status: some View {
        switch model.phase {
        case .idle, .fetchingDescription:
            ViewportStatus.loading("Reading the robot's description…", progress: nil)
        case let .downloadingMeshes(completed, total):
            // The first visit pulls every mesh over the robot's own Wi-Fi, which
            // is slow enough that a bare spinner reads as a hang.
            ViewportStatus.loading(
                "Downloading model \(completed)/\(total)…",
                progress: total > 0 ? Double(completed) / Double(total) : nil
            )
        case .buildingScene:
            ViewportStatus.loading("Building the scene…", progress: nil)
        case .ready:
            EmptyView()
        case let .failed(message):
            ContentUnavailableView(
                "Could not load the model",
                systemImage: "exclamationmark.triangle",
                description: Text(message)
            )
        }
    }

    private var options: some View {
        Menu {
            Button {
                model.camera.reset()
            } label: {
                Label("Reset view", systemImage: "arrow.counterclockwise")
            }
            Divider()
            Toggle("Place head from pose", isOn: Binding(
                get: { model.placesHeadDirectly },
                set: { model.placesHeadDirectly = $0 }
            ))
            Toggle("Solve Stewart linkage", isOn: Binding(
                get: { model.solvesPassiveJoints },
                set: { model.solvesPassiveJoints = $0 }
            ))
            if let lastFrameAt = model.lastFrameAt {
                Text("Last frame \(lastFrameAt.formatted(date: .omitted, time: .standard))")
            }
            Text("Decoded frames: \(model.streamDiagnostics.decodedFrames)")
        } label: {
            Label("Options", systemImage: "ellipsis.circle")
                .labelStyle(.iconOnly)
        }
        .viewportControlStyle()
        .padding(12)
    }
}

import ReachyKit
import ReachyMedia
import SwiftUI

/// Robot camera + two-way audio over WebRTC. Video and robot audio play as soon
/// as the session negotiates; the mic button unmutes the client → robot audio
/// uplink (robot speaker). A joystick drives head yaw/pitch so you can look
/// around without leaving the video.
struct CameraViewport: View {
    let session: CameraSession
    let address: RobotAddress

    @State private var teleop: SetTargetClient?
    @State private var target = SetTargetClient.Target()

    /// Same comfortable head range as `ControllerScreen`; the daemon clamps anyway.
    private let headAngle = 40.0 * .pi / 180

    var body: some View {
        CameraVideoView(track: session.videoTrack)
            .background(Color.black)
            .overlay(alignment: .center) { status }
            .overlay(alignment: .topTrailing) { micButton }
            .safeAreaInset(edge: .bottom) { joystick }
            .onAppear { connectTeleop() }
            .onDisappear {
                let teleop = teleop
                self.teleop = nil
                Task { await teleop?.disconnect() }
            }
    }

    @ViewBuilder
    private var status: some View {
        switch session.phase {
        case .connecting:
            ProgressView("Connecting…")
                .tint(.white)
                .foregroundStyle(.white)
        case .waitingForProducer:
            ContentUnavailableView(
                "Waiting for camera",
                systemImage: "video",
                description: Text("The robot has not registered a video stream yet.")
            )
        case let .failed(message):
            ContentUnavailableView(
                "Camera unavailable",
                systemImage: "video.slash",
                description: Text(message)
            )
        case .streaming:
            EmptyView()
        }
    }

    private var micButton: some View {
        Button {
            session.setMicEnabled(!session.isMicEnabled)
        } label: {
            Label(
                session.isMicEnabled ? "Mute microphone" : "Unmute microphone",
                systemImage: session.isMicEnabled ? "mic.fill" : "mic.slash"
            )
            .labelStyle(.iconOnly)
            .foregroundStyle(session.isMicEnabled ? .red : .secondary)
        }
        .viewportControlStyle()
        .disabled(session.phase != .streaming)
        .padding(12)
    }

    @ViewBuilder
    private var joystick: some View {
        if session.phase == .streaming {
            JoystickPad { x, y in
                target.yaw = -x * headAngle
                target.pitch = y * headAngle
                push()
            }
            .frame(width: 140, height: 140)
            .frame(maxWidth: .infinity, alignment: .trailing)
            .padding()
        }
    }

    private func connectTeleop() {
        guard teleop == nil, let client = try? SetTargetClient(address: address) else { return }
        teleop = client
        Task { await client.connect() }
    }

    private func push() {
        guard let teleop else { return }
        let target = target
        Task { await teleop.send(target) }
    }
}

import SwiftUI

/// The one place a live view of the robot is mounted.
///
/// There is deliberately no second instance anywhere: `RobotSceneView` hands the
/// scene's root entity to `RealityView`, and an entity has exactly one parent, so
/// a second viewport would silently steal the robot from the first.
struct ViewportView: View {
    let model: ViewportModel
    /// The robot reports no camera at all on a wired unit — then there is nothing
    /// to switch between and the control is hidden rather than disabled.
    let offersCamera: Bool

    var body: some View {
        content
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .overlay(alignment: .topLeading) { switcher }
    }

    @ViewBuilder
    private var content: some View {
        if let setupError = model.setupError {
            ContentUnavailableView(
                "Viewport unavailable",
                systemImage: "exclamationmark.triangle",
                description: Text(setupError)
            )
        } else {
            switch model.content {
            case .scene:
                if let sceneModel = model.sceneModel {
                    SceneViewport(model: sceneModel)
                } else {
                    ViewportStatus.loading("Connecting…", progress: nil)
                }
            case .camera:
                if let session = model.cameraSession, let address = model.address {
                    CameraViewport(session: session, address: address)
                } else {
                    ViewportStatus.loading("Connecting…", progress: nil)
                }
            }
        }
    }

    @ViewBuilder
    private var switcher: some View {
        if offersCamera {
            Picker("Viewport", selection: Binding(
                get: { model.content },
                set: { model.setContent($0) }
            )) {
                ForEach(ViewportModel.Content.allCases) { content in
                    Label(content.title, systemImage: content.systemImage).tag(content)
                }
            }
            .pickerStyle(.segmented)
            .labelsHidden()
            .frame(maxWidth: 240)
            .padding(12)
        }
    }
}

/// Shared chrome so the scene and the camera report progress the same way.
enum ViewportStatus {
    static func loading(_ title: String, progress: Double?) -> some View {
        VStack(spacing: 12) {
            if let progress {
                ProgressView(value: progress)
                    .frame(maxWidth: 220)
            } else {
                ProgressView()
            }
            Text(title)
                .font(.callout)
                .foregroundStyle(.secondary)
        }
        .padding(20)
        .background(.regularMaterial, in: RoundedRectangle(cornerRadius: 12))
    }
}

extension View {
    /// Floating controls sit on top of video and 3D alike, so they carry their own
    /// backing rather than relying on whatever is behind them for contrast.
    func viewportControlStyle() -> some View {
        font(.title3)
            .padding(8)
            .background(.regularMaterial, in: Circle())
    }
}

