import Foundation
import Observation
import ReachyKit

/// Speaker and microphone levels.
///
/// The sliders track a local value and only reach the daemon when a gesture ends:
/// `POST /api/volume/set` plays a test sound on every accepted call, so a slider
/// that sent on change would make the robot beep continuously.
@MainActor
@Observable
final class AudioSettingsModel {
    var speakerPercent: Double = 0
    var microphonePercent: Double = 0

    private(set) var speaker: AudioLevel?
    private(set) var microphone: AudioLevel?
    private(set) var isLoading = false
    private(set) var isBusy = false
    private(set) var errorMessage: String?

    private var hasLoaded = false

    var isReady: Bool {
        speaker != nil || microphone != nil
    }

    /// Safe to call from `.task` on every appearance — it fetches once and then
    /// leaves the sliders alone, so a redraw can never yank a value the user is
    /// in the middle of dragging.
    func load(session: RobotSession) async {
        guard !hasLoaded, !isLoading else { return }
        isLoading = true
        defer { isLoading = false }
        do {
            // Sequential rather than concurrent: two calls against a robot that
            // has no audio device would report the same failure twice.
            adoptSpeaker(try await session.volume())
            adoptMicrophone(try await session.microphoneVolume())
            errorMessage = nil
            hasLoaded = true
        } catch {
            errorMessage = Self.describe(error)
        }
    }

    func commitSpeaker(session: RobotSession) async {
        let percent = Int(speakerPercent.rounded())
        // Touching the slider without moving it must not trigger the test sound.
        guard percent != speaker?.percent else { return }
        await commit(percent) { adoptSpeaker(try await session.setVolume($0)) }
    }

    func commitMicrophone(session: RobotSession) async {
        let percent = Int(microphonePercent.rounded())
        guard percent != microphone?.percent else { return }
        await commit(percent) { adoptMicrophone(try await session.setMicrophoneVolume($0)) }
    }

    func playTestSound(session: RobotSession) async {
        await commit(nil) { _ in try await session.playTestSound() }
    }

    private func commit(_ percent: Int?, _ call: (Int) async throws -> Void) async {
        isBusy = true
        defer { isBusy = false }
        do {
            try await call(percent ?? 0)
            errorMessage = nil
        } catch {
            errorMessage = Self.describe(error)
        }
    }

    /// The daemon answers with what it actually applied, which may be clamped, so
    /// the slider follows the robot rather than the other way round.
    private func adoptSpeaker(_ level: AudioLevel) {
        speaker = level
        speakerPercent = Double(level.percent)
    }

    private func adoptMicrophone(_ level: AudioLevel) {
        microphone = level
        microphonePercent = Double(level.percent)
    }

    private static func describe(_ error: any Error) -> String {
        (error as? LocalizedError)?.errorDescription ?? String(describing: error)
    }
}

import ReachyKit
import SwiftUI

/// Robot speaker and microphone levels, as a `Form` section.
struct AudioSettingsSection: View {
    let session: RobotSession

    @State private var model = AudioSettingsModel()

    var body: some View {
        @Bindable var model = model
        Section("Audio") {
            if model.isLoading, !model.isReady {
                ProgressView()
            } else {
                level(
                    "Speaker",
                    systemImage: "speaker.wave.2",
                    value: $model.speakerPercent,
                    device: model.speaker
                ) {
                    await model.commitSpeaker(session: session)
                }
                level(
                    "Microphone",
                    systemImage: "mic",
                    value: $model.microphonePercent,
                    device: model.microphone
                ) {
                    await model.commitMicrophone(session: session)
                }
                Button("Test sound") {
                    Task { await model.playTestSound(session: session) }
                }
                .disabled(model.isBusy || !model.isReady)
            }
            if let errorMessage = model.errorMessage {
                Text(errorMessage)
                    .font(.caption)
                    .foregroundStyle(.red)
            }
        }
        .task { await model.load(session: session) }
    }

    private func level(
        _ title: String,
        systemImage: String,
        value: Binding<Double>,
        device: AudioLevel?,
        commit: @escaping () async -> Void
    ) -> some View {
        VStack(alignment: .leading, spacing: 2) {
            HStack {
                Label(title, systemImage: systemImage)
                Spacer()
                Text("\(Int(value.wrappedValue.rounded()))%")
                    .font(.caption.monospaced())
                    .foregroundStyle(.secondary)
            }
            // The daemon reaches the robot's audio through one named sink or
            // source; a robot with several gives no other hint which one moved.
            Slider(value: value, in: 0 ... 100, step: 1) { editing in
                guard !editing else { return }
                Task { await commit() }
            }
            if let device {
                Text("\(device.device) · \(device.platform)")
                    .font(.caption2)
                    .foregroundStyle(.tertiary)
            }
        }
        .disabled(device == nil)
    }
}

