316	// MARK: - Wake / sleep
317	
318	/// Both transitions are multi-step protocols against the daemon, not single
319	/// calls: `/move/play/wake_up` and `/move/play/goto_sleep` only play animations
320	/// and never touch the motor control mode, and they answer 503 while the robot
321	/// backend is down. Enabling and cutting motor power is the caller's job.
322	public extension RobotSession {
323	    /// The branch is picked from a freshly fetched status rather than `lastStatus`,
324	    /// which may be a poll interval out of date — long enough to send motor
325	    /// commands at a backend that is already gone.
326	    func wake() async {
327	        guard let client, powerTransition == nil else { return }
328	        lastError = nil
329	        // Claimed before the first suspension point: `@MainActor` re-enters on
330	        // every `await`, so a later latch would let a double tap through.
331	        powerTransition = .wakingUp
332	        defer { powerTransition = nil }
333	        do {
334	            let status = try await client.daemonStatus()
335	            lastStatus = status
336	            guard status.state == .running else {
337	                // `wake_up=true` has the daemon enable the motors and play the
338	                // animation itself once the backend is up.
339	                powerTransition = .startingBackend
340	                try await client.startDaemon(wakeUp: true)
341	                if await !waitForDaemonRunning(client: client) {
342	                    lastError = "Robot backend did not start within \(configuration.daemonStartTimeout)."
343	                }
344	                return
345	            }
346	            try await client.setMotorMode(.enabled)
347	            try await Task.sleep(for: configuration.motorSettleDelay)
348	            let uuid = try await client.wakeUp()
349	            await waitForMoveToFinish(uuid, client: client)
350	        } catch {
351	            lastError = Self.describe(error)
352	        }
353	    }
354	
355	    /// Mirror image of wake: the animation must finish *before* power is cut,
356	    /// otherwise the head drops wherever it happens to be.
357	    func sleep() async {
358	        guard let client, powerTransition == nil else { return }
359	        lastError = nil
360	        powerTransition = .goingToSleep
361	        defer { powerTransition = nil }
362	        do {
363	            let uuid = try await client.gotoSleep()
364	            await waitForMoveToFinish(uuid, client: client)
365	            try await client.setMotorMode(.disabled)
366	        } catch {
367	            lastError = Self.describe(error)
368	        }
369	    }
370	}
371	
372	private extension RobotSession {
373	    /// Polls the daemon's authoritative running-move list until `uuid` is gone.
374	    /// A timeout returns normally: parking the motors matters more than proof
375	    /// that the animation ran to completion.
376	    func waitForMoveToFinish(_ uuid: String, client: any RobotAPIClient) async {
377	        let deadline = ContinuousClock.now + configuration.moveCompletionTimeout
378	        while ContinuousClock.now < deadline, !Task.isCancelled {
379	            try? await Task.sleep(for: configuration.movePollInterval)
380	            guard let running = try? await client.runningMoveUUIDs() else { continue }
381	            if !running.contains(uuid) {
382	                return
383	            }
384	        }
385	    }
386	
387	    /// Waits out the background start job, refreshing `lastStatus` as it goes.
388	    func waitForDaemonRunning(client: any RobotAPIClient) async -> Bool {
389	        let deadline = ContinuousClock.now + configuration.daemonStartTimeout
390	        while ContinuousClock.now < deadline, !Task.isCancelled {
391	            try? await Task.sleep(for: configuration.pollInterval)
392	            guard let status = try? await client.daemonStatus() else { continue }
393	            lastStatus = status
394	            switch status.state {
395	            case .running: return true
396	            case .error, .stopped: return false
397	            default: continue
398	            }
399	        }
400	        return false
401	    }
